#include <iostream>
#include <cstdint>

int64_t a[9];

int main() {
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(nullptr);

    for (uint64_t k = 1; k <= 8; ++k) {
        uint64_t l = (1ULL << k) - 1;
        uint64_t r = 1ULL << (k - 1);
        uint64_t v = l * r;
        a[k] = static_cast<int64_t>(v);
    }

    int64_t n;
    std::cin >> n;

    for (int64_t k = 8; k >= 1; --k) {
        if (n >= a[k] && n % a[k] == 0) {
            std::cout << a[k] << '\n';
            return 0;
        }
    }

    return 0;
}

